with scored as (select id, reading_ts, temp_c, humidity, stddev_samp(pressure) over (partition by device_code) as device_code_stddev_samp_pressure, dense_rank() over (partition by device_code order by status_bits) as status_bits_dense_rank, lag(temp_c, 1, 0) over (partition by device_code order by reading_ts, id) as prev_temp_c from device_readings where temp_c >= 34) select case when status_bits_dense_rank >= 7 then 'PREMIUM' else 'STANDARD' end as status_bits_dense_rank_tier, count(*) as cnt, percentile_approx(humidity, 0.9) as humidity_p90, sum(device_code_stddev_samp_pressure) as total_device_code_stddev_samp_pressure from scored group by 1 having total_device_code_stddev_samp_pressure > 0 order by cnt desc
